from __future__ import annotations

import base64
import json
import zlib
from pathlib import Path

PAYLOAD = (
''
''
''
''
''
)

content = zlib.decompress(base64.b64decode(PAYLOAD))
source = Path('data/course_redevelopment/biofotonica/units/unit-05.json')
mirror = Path('data/generated_units/biofotonica/unit-05.json')
source.write_bytes(content)
mirror.write_bytes(content)

unit = json.loads(content.decode('utf-8'))
assert unit['status'] == 'review'
assert len(unit['theory_sections']) == 4
assert len(unit['glossary']) >= 16
assert len(unit['worked_examples']) >= 5
assert len(unit['self_assessment']) >= 10
assert len(unit['sources']) >= 8
assert 'Concepto de la unidad que debe definirse' not in content.decode('utf-8')
assert 'SNR}_{dB}' not in content.decode('utf-8')

test = '''from __future__ import annotations

import json
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "data" / "course_redevelopment" / "biofotonica" / "units" / "unit-05.json"
MIRROR = ROOT / "data" / "generated_units" / "biofotonica" / "unit-05.json"
GENERIC = "concepto de la unidad que debe definirse mediante entidades observables"


class BiofotonicaUnit05CuratedTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.unit = json.loads(SOURCE.read_text(encoding="utf-8"))

    def test_exact_redevelopment_mirror(self) -> None:
        self.assertEqual(SOURCE.read_bytes(), MIRROR.read_bytes())
        self.assertEqual(self.unit["schema_version"], "2.0")
        self.assertEqual(self.unit["unit"], 5)
        self.assertEqual(self.unit["status"], "review")

    def test_generic_template_and_unrelated_snr_are_removed(self) -> None:
        text = SOURCE.read_text(encoding="utf-8").casefold()
        self.assertNotIn(GENERIC, text)
        self.assertNotIn("snr}_{db}", text)
        for concept in ("terapia fotodinámica", "fluence rate", "arrhenius", "incertidumbre", "iec 60601-2-22"):
            self.assertIn(concept, text)

    def test_theory_and_equations_are_dosimetry_specific(self) -> None:
        sections = self.unit["theory_sections"]
        self.assertEqual(len(sections), 4)
        self.assertTrue(all(len(s["paragraphs"]) >= 4 for s in sections))
        self.assertTrue(all(len(s["key_points"]) >= 4 for s in sections))
        equations = {eq["latex"] for s in sections for eq in s.get("equations", [])}
        self.assertIn("E_e=\\frac{P}{A}", equations)
        self.assertIn("H_e=\\int_0^t E_e(\\tau)\\,d\\tau", equations)
        self.assertTrue(any("Omega" in eq or "\\Omega" in eq for eq in equations))

    def test_pedagogical_scaffolding_is_substantive(self) -> None:
        self.assertGreaterEqual(len(self.unit["glossary"]), 16)
        self.assertGreaterEqual(len(self.unit["worked_examples"]), 5)
        self.assertGreaterEqual(len(self.unit["common_errors"]), 8)
        self.assertGreaterEqual(len(self.unit["self_assessment"]), 10)
        activity = self.unit["guided_activities"][0]
        self.assertGreaterEqual(len(activity["instructions"]), 6)
        self.assertGreaterEqual(len(activity["problems"]), 12)
        self.assertGreaterEqual(len(activity["deliverables"]), 8)
        self.assertGreaterEqual(len(activity["checking_criteria"]), 10)

    def test_sources_are_traceable_and_current_safety_scope_is_explicit(self) -> None:
        sources = self.unit["sources"]
        self.assertGreaterEqual(len(sources), 8)
        self.assertTrue(all(s.get("verification_status") == "verified_directly" for s in sources))
        urls = {s["url"] for s in sources}
        self.assertIn("https://www.aapm.org/pubs/reports/detail.asp?docid=124", urls)
        self.assertIn("https://aapm.onlinelibrary.wiley.com/doi/10.1002/mp.17613", urls)
        self.assertIn("https://webstore.iec.ch/en/publication/3587", urls)
        self.assertIn("https://webstore.iec.ch/en/publication/106555", urls)

    def test_clinical_boundary_is_explicit(self) -> None:
        notice = self.unit["editorial_notice"].casefold()
        purpose = self.unit["purpose"].casefold()
        self.assertIn("no constituye revisión disciplinar externa", notice)
        self.assertIn("no requiere exposición óptica real", notice)
        self.assertIn("recomendaciones clínicas", purpose)
        self.assertIn("parámetros de tratamiento", purpose)


if __name__ == "__main__":
    unittest.main()
'''
Path('tests/test_biofotonica_unit_05_curated.py').write_text(test, encoding='utf-8')
print('Biofotónica U5 curated and regression test written.')
